import json
from pathlib import Path
root=Path(__file__).parent
rows=[
dict(n=1,title='FX-10（エフェックス・テン）',subtype='医療用ドロイド',lore='帝国軍の野戦部隊に配備される標準型医療用ドロイド。プログラムの強化によりFX-10は戦闘で生じ得る様々な種類の負傷を手当することができる。',game='1ターンに1回、同じ位置か隣接位置で武器が“命中”したドロイド以外のキャラクターを1名、ロストデッキの代わりにユーズドデッキに移せる。',translated_title='FX-10 (Effex-ten).',translated_subtype='Medical droid.',translated_lore='A standard medical droid deployed with Imperial field units. Enhanced programming lets FX-10 treat many kinds of wounds that may occur in battle.',translated_game='Once per turn, one non-droid character hit by a weapon at the same or an adjacent location may be moved to the Used Deck instead of the Lost Deck.',destiny='2',power='1',deploy='2',forfeit='3',uniqueness='Unrestricted',icons='[[Droid]]'),
dict(n=2,title='＊ホス：エコー基地司令センター（戦略司令室）',light_text='ここに存在しているなら、自分の宇宙船はホスの位置からホスの星系に移動する際フォースを消費しない。',dark_text='ホス（星系）を目標とする場合、「発射準備開始せよ」の合計値に1を加える。',translated_title='Hoth: Echo Base Command Center (Strategic Command Room).',translated_light='If you have presence here, your starships spend no Force when moving from a Hoth location to the Hoth system.',translated_dark='When targeting Hoth (the system), add 1 to the total of Commence Primary Ignition.',dark_icons='1',light_icons='1',uniqueness='Unique',icons='[[Planet]] [[Interior]] [[Underground]] [[Scomp Link]]',image_rotation='left',image_rotated_height='166'),
dict(n=3,title='EG-4（イージー・フォー）',subtype='パワー・ドロイド',lore='単純な構造をしたドロイドで、環境の苛烈な地域で広く使用されている。改造により、上部にパワー・ソケットが追加されている。ボサンの地下組織が同盟軍に提供した。',game='その場所にいるパワー・ドロイド以外のすべての自分のドロイドの戦闘力に、それぞれ1を加える。＊このカードの運命数は0である、ただし、戦闘運命数として引いた場合で、味方の合計戦闘力が敵より小さい場合に限り、合計戦闘力を2倍にする。この効果は、1度の戦闘に1回しか使えない。',translated_title='EG-4 (Eegee-Four).',translated_subtype='Power droid.',translated_lore='A simply constructed droid widely used in harsh environments. Modifications have added power sockets on top. Supplied to the Alliance by the Bothan underground.',translated_game="Adds 1 to the power of each of your other droids at the same place, excluding power droids. *This card's destiny is 0. However, if drawn as battle destiny when your total power is lower than the enemy's, double your total power. This effect may be used only once per battle.",destiny='*',power='0',deploy='1',forfeit='3',uniqueness='Unrestricted',icons='[[Droid]]'),
dict(n=4,title='FX-7（エフェックス・セブン）',subtype='医療用ドロイド',lore='エコー基地の反乱軍が“フィクスイット（修理屋）”と呼んでいるモデル。最新の医療施設では時代遅れの旧式とみなされているが、反乱軍の前哨地の多くでは、反乱軍の前線基地の多くでは、いまだに医療アシスタントとして現役である。',game='1ターンに1回、同じ位置か隣接位置で武器が“命中”したドロイド以外のキャラクターを1名、ロストデッキの代わりにユーズドデッキに移せる。バクタ・タンクのXの値から2を引ける（累積可能）。',translated_title='FX-7 (Effex-Seven).',translated_subtype='Medical droid.',translated_lore='A model the Rebels at Echo Base call “Fixit (repairman).” Although considered obsolete at modern medical facilities, at many Rebel outposts, at many Rebel front-line bases, it remains in service as a medical assistant.',translated_game="Once per turn, one non-droid character hit by a weapon at the same or an adjacent location may be moved to the Used Deck instead of the Lost Deck. May subtract 2 from Bacta Tank's X value (cumulative).",translation_note='The Japanese lore repeats the location clause, first 前哨地 (outpost) and then 前線基地 (front-line base).',destiny='2',power='0',deploy='2',forfeit='3',uniqueness='Unrestricted',icons='[[Droid]]'),
dict(n=5,title='＊ホス：エコー基地司令センター（戦略司令室）',light_text='ここで戦闘を宣言したなら戦闘運命数を1枚多く加える。ここを支配しているなら、フォース消耗に－1。',dark_text='ここを支配しており、ここにX人のリーダーがいるなら、ホスの各ロケーションでの合計戦闘力に＋X。',translated_title='Hoth: Echo Base Command Center (Strategic Command Room).',translated_light='If you initiate a battle here, add one additional battle destiny. If you control here, Force drains are −1.',translated_dark='If you control here and have X leaders here, total power at each Hoth location is +X.',dark_icons='0',light_icons='2',uniqueness='Unique',icons='[[Planet]] [[Interior]] [[Underground]] [[Scomp Link]]',image_rotation='left',image_rotated_height='167'),
dict(n=6,title='＊先頭機は任せろ',subtype='ロスト・インタラプト',lore='ヤヴィンの戦いにおけるデス・スターの防衛戦で、ダース・ベイダーはブラック2とブラック3を従え、3機編隊の先頭にたって攻撃を行った。',game='どちらかを選ぶ。1：「アタック・ラン」を行っている宇宙戦闘機を1機、目標として選ぶ。運命数を引き、デス・スター上にあるTIEの1機につき、1を加える。合計の値＞目標の回避値なら、宇宙戦闘機はロストする。2：このターンの終了時まで、任意の1機の宇宙戦闘機の武器運命数に、それぞれ1を加える。',translated_title='Leave the lead fighter to me.',translated_subtype='Lost Interrupt.',translated_lore='While defending the Death Star during the Battle of Yavin, Darth Vader attacked at the head of a three-fighter formation, with Black 2 and Black 3 following him.',translated_game='Choose one: (1) Target one starfighter making an Attack Run. Draw destiny and add 1 for each TIE at Death Star. If the total exceeds the target’s maneuver, the starfighter is lost. (2) Until the end of this turn, add 1 to each weapon-destiny value for any one starfighter.',destiny='3',uniqueness='Unique'),
dict(n=7,title='＊R3-T6（アースリー・ティーシクス）',subtype='操縦ドロイド',lore='R3ユニットは旧型のR1にくらべて、大容量のメモリと、より優れた演算回路を持っており、航路計算をより効率的に行える。R3-T6はデス・スターに配属された。',game='搭乗する大型艦の戦闘力に＋1、航行速度に＋2。加えてその大型艦は耐：損耗＜4を得る。「デス・スター：中央コア」にいるなら、「デス・スター」星系カードの航行速度に1を加える。',translated_title='R3-T6 (Arthree-Teesix).',translated_subtype='Piloting droid.',translated_lore='Compared with the older R1 model, R3 units have more memory and better computation circuits, allowing more efficient navigation calculations. R3-T6 was assigned to the Death Star.',translated_game='Adds 1 to the power and 2 to the hyperspeed of the capital starship aboard which it is deployed. That capital starship also gains immunity to attrition <4. If at Death Star: Central Core, adds 1 to the hyperspeed of the Death Star system card.',destiny='2',power='1',deploy='2',forfeit='3',uniqueness='Unique',icons='[[Droid]]'),
dict(n=8,title='R5-D4（アーファイブ・ディーフォー）',subtype='操縦ドロイド',lore='ただ単に“赤いやつ”と呼ばれることの多い安物の操縦ドロイド。タトゥイーンでC-3POと離れ離れになるのを恐れたR2-D2が、あらかじめこのドロイドのスターターを細工して故障させた。操縦の腕は悪いが、整備ドロイドとしては優秀。',game='搭乗している宇宙船の戦闘力と回避値に1を加える。搭乗する宇宙船がイオン砲の命中を受けた場合、次の自分の支配フェイズに装甲値／回避値および航行速度を回復させられる。',translated_title='R5-D4 (Arfive-Defour).',translated_subtype='Piloting droid.',translated_lore='A cheap piloting droid often called simply “the red one.” Fearing separation from C-3PO on Tatooine, R2-D2 sabotaged this droid’s starter in advance so that it would break down. A poor pilot, but an excellent maintenance droid.',translated_game='Adds 1 to the power and maneuver of the starship aboard which it is deployed. If that starship is hit by an ion cannon, may restore its armor/maneuver and hyperspeed during your next control phase.',destiny='4',power='1',deploy='2',forfeit='3',uniqueness='Unrestricted',icons='[[Droid]]'),
dict(n=9,title='RA-7（アーレイ・セブン）',subtype='サーバント・ドロイド',lore='RA系サーバント・ドロイドの基本プログラムは、第5種のものだ。知能は低く、召し使いの仕事をこなせる程度でしかない。貴族や高官たちに広く愛用されている。',game='同じ場所にいるキャラクターが武器を持っているなら、自分の配備フェイズに武器をこのドロイドに渡すことができる。RA-7は4つまでの武器を運ぶことができ、同じ場所にいる戦士にコストなしで再配備することができる。ただし、RA-7自体は武器を使用できない。',translated_title='RA-7 (Aray-Seven).',translated_subtype='Servant droid.',translated_lore='RA-series servant droids have fifth-class basic programming. Their intelligence is low and sufficient only for servants’ work. Widely favored by nobles and senior officials.',translated_game='If a character at the same place has a weapon, you may transfer it to this droid during your deploy phase. RA-7 may carry up to four weapons and redeploy them for no cost on warriors at the same place. RA-7 itself cannot use weapons.',destiny='4',power='1',deploy='2',forfeit='3',uniqueness='Unrestricted',icons='[[Droid]]'),
]
assert len(rows)==9
(root/'phase3-readings.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf8')
print('Nine inspected printed faces transcribed, translated and recorded; no English card text substituted')
